//! PWM pad functions of the SWM341 pin matrix.
//!
//! Generated by `scripts/gen_pin_func.py` from the vendor header
//! `SWM341_port.h` -- do not edit by hand.
//!
//! Each `Pin{n}Func` enumerates the PWM functions selectable on pin `{n}` of its
//! bank; the numeric value of every variant is the 4-bit code written into
//! `PORTx.FUNC0/FUNC1`. `PWMx{ A, B, AN, BN }` are the channel outputs, plus the
//! `PWM_BRKx` break and `PWM_CLKx` clock inputs. Code `0` (generic GPIO) is
//! omitted. Apply a variant with [`crate::gpio::set_function`] after
//! [`crate::gpio::acquire`].


/// Generate the per-pin `Pin{n}Func` enums for one bank module.
///
/// Each entry is `PinType => Enum { Variant = func_code, ... }`; the macro
/// writes the `#[repr(u8)]` enum plus its `PinFunc` / `PinFuncOf` impls.
macro_rules! pad_funcs {
    ( $( $pin_ty:ident => $enum:ident { $( $var:ident = $val:literal ),* $(,)? } ),* $(,)? ) => {
        $(
            #[derive(Clone, Copy, PartialEq, Eq, Debug)]
            #[repr(u8)]
            pub enum $enum {
                $( $var = $val ),*
            }
            impl crate::gpio::PinFunc for $enum {
                #[inline]
                fn value(self) -> u8 { self as u8 }
            }
            impl crate::gpio::PinFuncOf<crate::gpio::$pin_ty> for $enum {}
        )*
    };
}

pub mod a {
    pad_funcs! {
        PA2 => Pin2Func { PwmBrk0 = 2 },
        PA5 => Pin5Func { PwmBrk1 = 1, PwmClk1 = 2 },
        PA6 => Pin6Func { PwmBrk0 = 2, PwmClk0 = 3 },
        PA10 => Pin10Func { PwmClk1 = 2 },
        PA11 => Pin11Func { PwmClk0 = 2 },
    }
}

